func tttEl(se *port.Cells, parent int32, role int32, size int32, fpg int32, scope int32, rs int32, cs int32) int32 {
	// Append an element: parent, standard type (`sr`: Table 42, TR 43, TH 44, TD 45, THead 46, TBody 47, TFoot 48), the rows of its subtree,
	// the page of its first text, Scope (0 none, 1 Row, 2 Column, 3 Both), RowSpan, ColSpan. Answers its row.
	var i int32 = 0
	for i < 64 {
		port.CellsPush(se, 0)
		i += 1
	}
	var at int32 = port.CellsLen(se) - 64
	port.CellsSet(se, at+1, parent)
	port.CellsSet(se, at+5, role)
	port.CellsSet(se, at+40, size)
	port.CellsSet(se, at+49, fpg)
	port.CellsSet(se, at+29, scope)
	port.CellsSet(se, at+30, rs)
	port.CellsSet(se, at+31, cs)
	return (port.CellsLen(se) / 64) - 1
}

func tttSs(ss *port.Cells, tables int32) int32 {
	// The document row with the count of tables the tree has, which is what `tt-grids` asks first.
	port.CellsDrop(ss, 0)
	var i int32 = 0
	for i < 96 {
		port.CellsPush(ss, 0)
		i += 1
	}
	port.CellsSet(ss, 58, tables)
	return 0
}

func tttSample(se *port.Cells, page0 int32) int32 {
	// Document / Table / THead { TR { TH(Column) TH(Column, ColSpan 2) } } / TBody { TR { TD(RowSpan 2) TD TD } TR { TD TD } }: three
	// rows and three columns, the second body row's cells placed after the rowspan's column. Every row's text is on page `page0` (0-based).
	port.CellsDrop(se, 0)
	tttEl(se, -1, 0, 14, -1, 0, -1, -1)
	tttEl(se, 0, 42, 13, -1, 0, -1, -1)
	tttEl(se, 1, 46, 4, -1, 0, -1, -1)
	tttEl(se, 2, 43, 3, page0, 0, -1, -1)
	tttEl(se, 3, 44, 1, page0, 2, -1, -1)
	tttEl(se, 3, 44, 1, page0, 2, -1, 2)
	tttEl(se, 1, 47, 8, -1, 0, -1, -1)
	tttEl(se, 6, 43, 4, page0, 0, -1, -1)
	tttEl(se, 7, 45, 1, page0, 0, 2, -1)
	tttEl(se, 7, 45, 1, page0, 0, -1, -1)
	tttEl(se, 7, 45, 1, page0, 0, -1, -1)
	tttEl(se, 6, 43, 3, page0, 0, -1, -1)
	tttEl(se, 11, 45, 1, page0, 0, -1, -1)
	tttEl(se, 11, 45, 1, page0, 0, -1, -1)
	return 0
}

func TestATaggedGridPlacesItsSpans(emonT *testing.T) {
	var se *port.Cells = port.NewCells()
	var ss *port.Cells = port.NewCells()
	var tg *port.Cells = port.NewCells()
	var ta *port.Cells = port.NewCells()
	var oc *port.Cells = port.NewCells()
	tttSample(se, 0)
	tttSs(ss, 1)
	port.AssertEq(emonT, tagtable.TtGrids(se, ss, 1, tg, ta, oc), 1, "one tagged table on page 1")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 0), 1, "it is the Table element")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 2), 3, "three rows")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 3), 3, "three columns: the second header spans two")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 5), 7, "seven cells")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 13), 1, "one head row: the TH of the THead")
	port.AssertEq(emonT, tagtable.TtCget(ta, 1, 4), 2, "the second header's ColSpan")
	port.AssertEq(emonT, tagtable.TtCget(ta, 1, 2), 1, "placed in the second column")
	port.AssertEq(emonT, tagtable.TtCget(ta, 2, 3), 2, "the first body cell's RowSpan")
	port.AssertEq(emonT, tagtable.TtCget(ta, 3, 2), 1, "the next cell of its row is in the second column")
	port.AssertEq(emonT, tagtable.TtCget(ta, 5, 1), 2, "the third row")
	port.AssertEq(emonT, tagtable.TtCget(ta, 5, 2), 1, "its first cell skips the column the rowspan holds")
	port.AssertEq(emonT, tagtable.TtCget(ta, 6, 2), 2, "and its second is the third column")
	port.AssertEq(emonT, tagtable.TtCget(ta, 0, 5), 11, "a TH with Scope Column in a THead: a header (1), for its column (2), in the head (8)")
	port.AssertEq(emonT, tagtable.TtCget(ta, 2, 5), 0, "a plain TD")
	port.AssertEq(emonT, tagtable.TtGrids(se, ss, 2, tg, ta, oc), 0, "no table has text on page 2")
	port.AssertEq(emonT, tagtable.TtGrids(se, ss, 1, tg, ta, oc), 1, "and the arenas are emptied each time")
	port.CellsSet(ss, 58, 0)
	port.AssertEq(emonT, tagtable.TtGrids(se, ss, 1, tg, ta, oc), 0, "a tree with no Table has none")
}

