func TestTheScoreIsAWeightedHarmonicMeanScaledByTheWeakestCheck(emonT *testing.T) {
	var tg *port.Cells = port.NewCells()
	var acc *port.Cells = port.NewCells()
	var i int32 = 0
	for i < 24 {
		port.CellsPush(tg, 0)
		i += 1
	}
	tagtable.TtSet(tg, 0, 16, 1000)
	tagtable.TtSet(tg, 0, 17, 1000)
	tagtable.TtSet(tg, 0, 18, 1000)
	tagtable.TtSet(tg, 0, 19, 800)
	tagtable.TtSet(tg, 0, 20, 1000)
	tagtable.TtSet(tg, 0, 21, 1000)
	port.AssertEq(emonT, tagtable.TtScore(tg, 0, acc), 864, "one check at 800 (the cover of a table that misses a row): 960 scaled by 900/1000")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 10), 1, "still confirmed")
	tagtable.TtSet(tg, 0, 21, 714)
	port.AssertEq(emonT, tagtable.TtScore(tg, 0, acc), 749, "the geometry agrees on 714 of the words and the cover is 800: partial")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 10), 2, "partial")
	tagtable.TtSet(tg, 0, 16, 667)
	tagtable.TtSet(tg, 0, 19, 1000)
	tagtable.TtSet(tg, 0, 21, 0)
	port.AssertEq(emonT, tagtable.TtScore(tg, 0, acc), 85, "two visual rows in a TR and a geometry that agrees with none of the words")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 10), 3, "contradicted")
	tagtable.TtSet(tg, 0, 16, -1)
	tagtable.TtSet(tg, 0, 17, -1)
	tagtable.TtSet(tg, 0, 18, -1)
	tagtable.TtSet(tg, 0, 19, -1)
	tagtable.TtSet(tg, 0, 20, -1)
	tagtable.TtSet(tg, 0, 21, -1)
	port.AssertEq(emonT, tagtable.TtScore(tg, 0, acc), 0, "a table with nothing to check scores nothing")
	port.AssertEq(emonT, tagtable.TtGet(tg, 0, 10), 3, "and is not believed")
}

